@push('script')<script>(() => { const type=document.getElementById('account_type'), details=document.getElementById('business-compliance'), inputs=details.querySelectorAll('.compliance-input'), required=new Set(['legal_business_name','website','operating_country','operating_region','industry','monthly_sms_volume','recipient_countries','sender_name','support_email','privacy_policy_url','public_business_address','prohibited_use_ack','opt_out_ack','documented_consent_ack','no_harvested_lists_ack','suspension_ack']); const update=()=>{const business=type.value && type.value!=='individual';details.classList.toggle('d-none',!business);inputs.forEach(input=>{input.disabled=!business;input.required=business&&required.has(input.name);});};type.addEventListener('change',update);update();})();</script>@endpush
